<template>
  <div class="factory-surface production-detail">
    <nav class="factory-breadcrumb" aria-label="页面路径"><NuxtLink to="/remotion"><ArrowLeft :size="14" />历史视频制作</NuxtLink><span>/</span><span>工作详情</span></nav>
    <div v-if="loading && !detail" class="factory-skeleton" role="status" aria-label="正在读取工作详情"><div v-for="n in 4" :key="n"></div></div>
    <div v-else-if="!detail" class="factory-empty"><Film :size="26" /><h1>暂时无法打开这个作品</h1><p role="alert">{{ error || '没有找到对应的制作记录。' }}</p><button class="btn" @click="refresh">重新读取</button></div>
    <template v-if="detail">
      <header class="factory-header detail-header"><div class="detail-identity"><div class="detail-episode-id">Episode {{ detail.episode.id }}<span v-if="detail.sourceId"> · 来源稿件 #{{ detail.sourceId }}</span><span v-if="detail.episode.episodeNumber > 1"> · 第 {{ detail.episode.episodeNumber }} 集</span></div><h1>{{ detail.episode.title || `第 ${detail.episode.episodeNumber} 集` }}</h1><div class="detail-meta"><span>集数 {{ detail.episode.episodeNumber }} · Episode ID {{ detail.episode.id }}</span><span class="factory-status" :class="productionTone(detail.job?.status)">{{ detail.job ? productionStatus(detail.job.status) : currentVideo ? '已有成片' : '尚未开始' }}</span><span v-if="detail.shots.length">{{ detail.shots.length }} 镜 · {{ productionDuration(totalDuration) }}</span></div></div>
        <div class="factory-actions"><NuxtLink v-if="detail.links.source" class="btn" :to="detail.links.source">回到原稿件</NuxtLink><button class="btn" :disabled="loading" @click="refresh"><RefreshCw :size="14" />刷新</button><button v-if="canRebuild" class="btn" :disabled="busy" title="复用当前正文、配音和素材制作新版本；旧成片保留" @click="rebuildProduction"><LoaderCircle v-if="busy" :size="15" class="spin" /><RefreshCw v-else :size="14" />{{ busy ? '正在提交…' : '重新制作' }}</button><button v-if="showProductionAction" class="btn btn-primary" :disabled="busy || running" @click="runProduction"><LoaderCircle v-if="busy || running" :size="15" class="spin" /><Play v-else :size="14" />{{ actionLabel }}</button><button v-else class="btn btn-primary" @click="activate('output')"><Play :size="14" />查看成片</button></div>
      </header>
      <div v-if="error" class="factory-notice error" role="alert">{{ error }}。保留上次读取的状态。<button class="text-button" @click="refresh">重新读取</button></div>
      <div v-if="actionError" class="factory-notice error" role="alert">{{ actionError }}</div>
      <div class="detail-body">
        <aside class="detail-sidebar">
          <nav class="detail-nav" aria-label="制作工作区"><button v-for="item in tabs" :id="`detail-tab-${item.id}`" :key="item.id" :aria-current="tab === item.id ? 'page' : undefined" :class="{active:tab === item.id}" @click="activate(item.id)"><component :is="item.icon" :size="16" /><span>{{ item.label }}</span><span v-if="item.id === 'shots'" class="nav-count">{{ detail.shots.length }}</span></button></nav>
          <div class="pipeline-progress"><h2>制作流程</h2><ol><li v-for="(step, index) in steps" :key="step.label" :class="{complete:step.complete,current:step.current}"><span class="step-indicator"><Check v-if="step.complete" :size="12" /><span v-else>{{ index + 1 }}</span></span><span>{{ step.label }}</span></li></ol><p>自动推进；重试复用有效工件。</p></div>
          <div class="detail-secondary"><NuxtLink :to="detail.links.episode"><ExternalLink :size="13" />打开 Episode 编辑</NuxtLink><button class="text-button" @click="tab = 'record'">查看制作记录</button></div>
        </aside>
        <main class="detail-main" :aria-labelledby="`detail-tab-${tab}`">
          <div v-if="detail.job" class="production-live" aria-live="polite"><div><LoaderCircle v-if="running" :size="16" class="spin" /><CircleAlert v-else-if="detail.job.status === 'failed'" :size="16" /><CheckCircle2 v-else-if="detail.job.status === 'completed'" :size="16" /><span>{{ detail.job.message || productionStatus(detail.job.status) }}</span></div><span>{{ productionDate(detail.job.updatedAt) }}</span></div>
          <div v-if="detail.job?.error" class="factory-notice error"><strong>{{ deliveryFailed ? '成片已保留，交付关联需要重试' : '制作暂停在当前步骤' }}</strong><p>{{ detail.job.error }}</p></div>
          <template v-if="tab === 'output'">
            <div class="output-layout"><section class="output-preview" aria-label="成片预览">
              <template v-if="currentVideo"><div v-if="videoError" class="factory-empty video-unavailable"><CircleAlert :size="28" /><h2>成片暂时无法播放</h2><p>可以打开文件检查，或重新尝试播放。</p><button class="btn" @click="videoError = false">重试播放</button><a class="btn" :href="currentVideo" target="_blank" rel="noreferrer">打开成片文件</a></div><video v-else :key="currentVideo" :src="currentVideo" controls playsinline preload="metadata" aria-label="历史视频成片" @error="videoError = true" /><div class="output-tools"><span>{{ selectedOutput?.filename || '当前成片' }}</span><button v-if="previewUrl && currentVideo !== previewUrl" class="btn btn-sm" @click="selectedUrl = previewUrl">带声精选</button><a class="btn btn-sm" :href="currentVideo" download><Download :size="14" />下载成片</a><a class="btn btn-sm" :href="currentVideo" target="_blank" rel="noreferrer">打开文件</a></div></template>
              <div v-else class="factory-empty output-empty"><Film :size="32" /><h2>{{ running ? '制作正在进行' : '成片将在这里出现' }}</h2><p>{{ running ? '可以离开此页，任务会在后台继续。完成后自动保存并关联原稿件。' : '确认文稿后开始制作。系统优先选用本地素材，用图片、地图或信息动画补足表达。' }}</p><div v-if="!detail.job" class="output-profile"><label for="production-profile">画面比例</label><select id="production-profile" v-model="profile" class="profile-select"><option value="16:9">横屏 16:9</option><option value="9:16">竖屏 9:16</option></select></div><button v-if="!running" class="btn btn-primary" :disabled="busy" @click="runProduction">{{ actionLabel }}</button></div>
            </section>
            <aside class="output-summary"><h2>交付概况</h2><dl><div><dt>画面比例</dt><dd>{{ detail.job?.profile || detail.episode.profile || profile }}</dd></div><div><dt>分镜与素材</dt><dd>{{ readyShots }} / {{ detail.shots.length }} 镜就绪</dd></div><div><dt>原稿关联</dt><dd>{{ associationLabel }}</dd></div><div v-if="detail.sourceId"><dt>百家号发表</dt><dd><RemotionPublicationStatus :source-id="detail.sourceId" :video-id="historicalOutput ? undefined : publicationVideoId" :historical-output="historicalOutput" /></dd></div><div><dt>技术检查</dt><dd>{{ technicalLabel }}</dd></div><div><dt>实际回看</dt><dd>{{ reviewLabel }}</dd></div></dl><p v-if="canRebuild" class="summary-note">重新制作会复用当前正文、配音和素材，保留旧版成片。</p><p v-if="!detail.job" class="summary-note">保留已有 Episode 和历史成片。开始制作后在这里跟踪统一流程。</p><p v-if="fallbacks.length" class="summary-note">{{ fallbacks.length }} 条素材补位或降级记录，<button class="text-button" @click="tab = 'shots'">查看逐镜信息</button>。</p><NuxtLink v-if="detail.links.source" class="delivery-link" :to="detail.links.source">打开原稿件与交付记录<ArrowRight :size="14" /></NuxtLink></aside></div>
            <section v-if="detail.outputs.length" class="output-history"><div class="section-heading"><h2>已保存的成片</h2><span>{{ detail.outputs.length }} 个版本</span></div><div v-for="output in detail.outputs" :key="output.id" class="output-history-row"><button class="text-button output-version" :class="{selected:currentVideo === output.url}" @click="chooseOutput(output)"><Play :size="13" /><span v-if="output.kind === 'preview'" class="shot-type">带声精选</span>{{ output.filename || '历史成片' }}</button><span>{{ productionDate(output.createdAt) }}</span><a :href="output.url" download aria-label="下载此版本"><Download :size="15" /></a></div></section>
          </template>
          <template v-else-if="tab === 'shots'">
            <div class="section-heading"><div><h2>逐镜表达与素材</h2><p>先看该镜要表达什么，再看实际使用的画面与来源。</p></div><span>{{ detail.shots.length }} 镜</span></div>
            <div v-if="!detail.shots.length" class="factory-empty"><Clapperboard :size="28" /><h2>分镜准备后显示在这里</h2><p>系统会按原文顺序设计镜头，保留旁白与时间对应关系。</p></div>
            <article v-for="(shot,index) in detail.shots" :key="shot.shotId" class="shot-row"><div class="shot-head"><strong>镜头 {{ String(index + 1).padStart(2,'0') }}</strong><span class="shot-type">{{ visualLabel(shot.visualType) }}</span><span>{{ productionDuration(shot.duration) }}</span><span v-if="shot.status === 'ready'" class="factory-status success">就绪</span></div><p class="shot-narration">{{ shot.narration }}</p><p v-if="shot.purpose" class="shot-purpose"><strong>表达目的</strong>{{ shot.purpose }}</p><dl class="shot-facts"><div v-if="shot.sourceNote"><dt>画面性质</dt><dd>{{ shot.sourceNote }}</dd></div><div v-if="shot.selection"><dt>选用素材</dt><dd><code>{{ shot.selection.assetId }}</code> · {{ Number(shot.selection.inPoint).toFixed(1) }}–{{ Number(shot.selection.outPoint).toFixed(1) }} 秒 · {{ cropLabel(shot.selection.crop) }}</dd></div><div v-if="shot.selection?.reason"><dt>选择理由</dt><dd>{{ shot.selection.reason }}</dd></div></dl><details class="shot-evidence"><summary>来源与编辑记录<span v-if="shot.candidatesCount"> · {{ shot.candidatesCount }} 条候选</span></summary><dl><div v-if="originalAnnotation(shot)"><dt>原素材标注</dt><dd>{{ originalAnnotation(shot) }}</dd></div><div><dt>画面核验</dt><dd>{{ evidenceLabel(shot) }}</dd></div><div v-if="shotPlan(shot).sourcePath"><dt>本地来源</dt><dd class="path-value">{{ shotPlan(shot).sourcePath }}</dd></div><div v-if="shotPlan(shot).mapReason"><dt>地图用途</dt><dd>{{ shotPlan(shot).mapReason }}</dd></div><div v-if="shotPlan(shot).map?.provenance"><dt>地图依据</dt><dd>{{ shotPlan(shot).map.provenance.attribution }}<br />{{ shotPlan(shot).map.provenance.source }}<br />{{ shotPlan(shot).map.provenance.license }}</dd></div><div v-if="shotPlan(shot).sourceEvidence"><dt>素材技术检查</dt><dd>{{ sourceTechnical(shot) }}</dd></div><div v-if="shotPlan(shot).titles?.length"><dt>动态文字</dt><dd>{{ shotPlan(shot).titles.map((t:any) => t.text).join('、') }}</dd></div><div v-if="shotPlan(shot).fallbackReason || shotFallback(shot.shotId)"><dt>补位记录</dt><dd>{{ shotPlan(shot).fallbackReason || shotFallback(shot.shotId) }}</dd></div></dl></details></article>
          </template>
          <template v-else-if="tab === 'script'">
            <div class="section-heading"><div><h2>文稿与配音</h2><p>制作使用此版本正文。需要改稿时回到来源编辑。</p></div><NuxtLink class="btn btn-sm" :to="detail.links.source || detail.links.episode">打开来源</NuxtLink></div>
            <section class="audio-section"><div><h3>配音母带</h3><p>{{ detail.episode.audioUrl ? '已保存的配音可直接试听。' : running ? '配音准备完成后可在这里试听。' : '制作时优先复用合格母带，没有可用母带时生成配音。' }}</p></div><audio v-if="detail.episode.audioUrl" :src="detail.episode.audioUrl" controls preload="metadata" aria-label="配音母带" /></section>
            <details v-if="detail.job?.plan?.timingEvidence" class="timing-record"><summary>配音与时间码记录</summary><pre>{{ pretty(detail.job.plan.timingEvidence) }}</pre></details>
            <div class="script-content">{{ detail.episode.script || '当前 Episode 尚无正文，请先打开来源补充。' }}</div>
          </template>
          <template v-else>
            <div class="section-heading"><div><h2>制作记录</h2><p>检查状态、补位原因与已保存的验收记录。</p></div><a v-if="detail.job" class="btn btn-sm" :href="`/api/v1/remotion/episodes/${episodeId}/history-production/evidence`" download><Download :size="14" />下载编辑记录</a></div>
            <dl class="record-facts"><div><dt>任务</dt><dd>{{ detail.job?.id || '尚未创建制作任务' }}</dd></div><div><dt>更新时间</dt><dd>{{ productionDate(detail.job?.updatedAt) }}</dd></div><div><dt>当前步骤</dt><dd>{{ stageLabel }}</dd></div><div><dt>交付关联</dt><dd>{{ associationLabel }}</dd></div><div><dt>回看记录</dt><dd>{{ reviewLabel }}</dd></div></dl>
            <details v-if="fallbacks.length" class="record-disclosure"><summary>补位与降级记录（{{ fallbacks.length }}）</summary><ul><li v-for="(item,index) in fallbacks" :key="index"><strong>{{ item.shotId || '制作任务' }}</strong> · {{ item.reason }}</li></ul></details>
            <details v-if="detail.job?.plan?.delivery" class="record-disclosure"><summary>技术验收原始记录</summary><pre>{{ pretty(detail.job.plan.delivery) }}</pre></details>
            <details v-if="detail.job?.scriptRevision" class="record-disclosure"><summary>正文版本标识</summary><code>{{ detail.job.scriptRevision }}</code></details>
            <div v-if="!running && currentVideo && !detail.job" class="legacy-production"><h3>使用统一流程制作新版本</h3><p>复用当前正文与可用工件，已有成片继续保留。</p><button class="btn" :disabled="busy" @click="runProduction">开始精细化制作</button></div>
            <details v-if="!running && detail.deletionSupported" class="record-disclosure danger-controls"><summary>管理此生产记录</summary><p>任务将从制作列表移除，原稿、成片文件和发布记录保留。</p><button v-if="!confirmDelete" class="btn" @click="confirmDelete = true">删除生产记录…</button><div v-else class="factory-actions"><span>确定删除 Episode {{ episodeId }}？</span><button class="btn" :disabled="deleting" @click="confirmDelete = false">取消</button><button class="btn danger-button" :disabled="deleting || busy" @click="deleteProduction">{{ deleting ? '删除中…' : '确认删除' }}</button></div></details>
          </template>
        </main>
      </div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, Check, CheckCircle2, CircleAlert, Clapperboard, Download, ExternalLink, FileText, Film, ListChecks, LoaderCircle, Play, RefreshCw } from 'lucide-vue-next'
import { historyProductionAPI, productionDate, productionDuration, productionRunning, productionStatus, productionTone, type HistoryProductionDetail } from '~/composables/useHistoryProduction'
import '~/assets/remotion-workspace.css'
const route = useRoute(), episodeId = computed(() => Number(route.params.id))
const detail = ref<HistoryProductionDetail | null>(null), loading = ref(false), error = ref(''), actionError = ref(''), busy = ref(false)
const profile = ref('16:9'), tab = ref('output'), selectedUrl = ref(''), videoError = ref(false), confirmDelete = ref(false), deleting = ref(false)
const tabs = [{id:'output',label:'成片与交付',icon:Film},{id:'shots',label:'分镜与素材',icon:Clapperboard},{id:'script',label:'文稿与配音',icon:FileText},{id:'record',label:'制作记录',icon:ListChecks}]
const running = computed(() => productionRunning(detail.value?.job?.status))
const latestVideo = computed(() => detail.value?.job?.plan?.deliveryAssociation?.videoUrl || detail.value?.outputs.find(o => !['preview','test'].includes(o.kind))?.url || detail.value?.episode.videoUrl || '')
const currentVideo = computed(() => selectedUrl.value || latestVideo.value)
const previewUrl = computed(() => detail.value?.job?.plan?.deliveryAssociation?.previewUrl || detail.value?.outputs.find(o => o.kind === 'preview')?.url)
const selectedOutput = computed(() => detail.value?.outputs.find(o => o.url === currentVideo.value))
const deliveryFailed = computed(() => detail.value?.job?.status === 'failed' && detail.value?.job?.stage === 'rendered')
const showProductionAction = computed(() => running.value || !currentVideo.value || ['failed','needs_review'].includes(detail.value?.job?.status || ''))
const canRebuild = computed(() => detail.value?.job?.status === 'completed' && !running.value)
const actionLabel = computed(() => busy.value ? '正在提交…' : running.value ? '制作中' : deliveryFailed.value ? '重试交付关联' : detail.value?.job?.status === 'failed' ? '从断点重试' : detail.value?.job ? '继续制作' : '开始精细化制作')
const readyShots = computed(() => detail.value?.shots.filter(s => s.status === 'ready').length || 0)
const totalDuration = computed(() => detail.value?.shots.reduce((n,s) => n+s.duration,0) || 0)
const fallbacks = computed(() => detail.value?.job?.plan?.fallbacks || [])
const associationLabel = computed(() => {const a = detail.value?.job?.plan?.deliveryAssociation; return a?.message || (a?.status === 'attached' ? '已关联原稿件' : a?.status === 'existing_preserved' ? '原交付已保留，新成片另存' : a?.status === 'failed' ? '关联失败，可重试' : detail.value?.sourceId ? '完成后自动关联' : '当前为独立 Episode')})
const publicationVideoId = computed(() => {const a = detail.value?.job?.plan?.deliveryAssociation; return a?.sourceDelivery?.videoId || a?.videoId})
const historicalOutput = computed(() => !!selectedUrl.value && selectedUrl.value !== latestVideo.value && selectedUrl.value !== previewUrl.value)
const technicalLabel = computed(() => {const report = detail.value?.job?.plan?.delivery; if (!report) return '尚无验收记录'; const qa = report.qa?.technical; return qa === 'passed' || qa === true || qa?.passed === true ? '技术检查通过' : qa === 'failed' || qa === false || qa?.passed === false ? '技术检查未通过' : '已保存检查记录'})
const reviewLabel = computed(() => {const review = detail.value?.job?.plan?.automaticDelivery; if (!review || (review.visualReview === 'not_performed' && review.listeningReview === 'not_performed')) return '未记录人工视听回看'; return '查看制作记录中的实际回看范围'})
const stageNames: Record<string,string> = {planning:'文稿与分镜',narration:'配音与时间码',selecting:'镜头素材',rendering:'合成成片',validating:'技术检查',rendered:'成片交付'}
const stageLabel = computed(() => stageNames[detail.value?.job?.stage || ''] || '尚未开始')
const steps = computed(() => {const job = detail.value?.job; const stage = ['planning','narration','selecting','rendering','validating','rendered'].indexOf(job?.stage || ''); const at = stage < 0 ? -1 : stage <= 1 ? 0 : stage === 2 ? 1 : stage === 3 ? 2 : 3; return ['文稿与配音','分镜与素材','合成成片','检查与交付'].map((label,index) => ({label,complete:job?.status === 'completed' || (!!job && index < at),current:!!job && index === at && job.status !== 'completed'}))})
let poll: ReturnType<typeof setTimeout> | undefined, disposed = false, generation = 0
async function refresh() { if (loading.value || busy.value || !Number.isInteger(episodeId.value)) return; const requestGeneration = generation; loading.value = true; try { const result = await historyProductionAPI.detail(episodeId.value); if (disposed || requestGeneration !== generation) return; detail.value = result; if (!result.job) profile.value = result.episode.profile || '16:9'; error.value = '' } catch(e:any) { if (requestGeneration === generation) error.value = e.message || '读取工作详情失败' } finally { loading.value = false; clearTimeout(poll); if (!disposed && requestGeneration === generation) poll = setTimeout(refresh,running.value ? 4000 : 12000) } }
async function runProduction() { if (busy.value || running.value || !detail.value) return; busy.value = true; generation++; clearTimeout(poll); actionError.value = ''; try { detail.value = await (detail.value.job ? historyProductionAPI.retry(episodeId.value,detail.value.job?.profile || detail.value.episode.profile || profile.value) : historyProductionAPI.start(episodeId.value,profile.value)); tab.value = 'output'; clearTimeout(poll); if (!disposed) poll = setTimeout(refresh,1500) } catch(e:any) { actionError.value = e.message || '提交制作失败，请重试' } finally { busy.value = false; if (!disposed) { clearTimeout(poll); poll = setTimeout(refresh,1500) } } }
async function rebuildProduction() { if (busy.value || running.value || !canRebuild.value) return; busy.value = true; generation++; clearTimeout(poll); actionError.value = ''; try { detail.value = await historyProductionAPI.rebuild(episodeId.value); selectedUrl.value = ''; tab.value = 'output'; clearTimeout(poll); if (!disposed) poll = setTimeout(refresh,1500) } catch(e:any) { actionError.value = e.message || '重新制作提交失败，请重试' } finally { busy.value = false; if (!disposed) { clearTimeout(poll); poll = setTimeout(refresh,1500) } } }
function activate(value: string) {tab.value = value}
function chooseOutput(output: HistoryProductionDetail['outputs'][number]) {selectedUrl.value = output.url; videoError.value = false}
function visualLabel(value?: string) {return ({video:'本地视频',image:'生成图片',map:'示意地图',graphic:'信息动画',auto:'待选画面'} as Record<string,string>)[value || ''] || '待选画面'}
function cropLabel(value: string) {return ({center:'居中裁切',cover:'铺满画面',contain:'完整画面',left:'保留左侧',right:'保留右侧'} as Record<string,string>)[value] || value}
function shotPlan(shot: HistoryProductionDetail['shots'][number]) {return detail.value?.job?.plan?.shots?.find((s:any) => s.shotId === shot.shotId) || detail.value?.job?.plan?.visuals?.[shot.shotId] || {}}
function shotFallback(id: string) {return fallbacks.value.filter((f:any) => f.shotId === id).map((f:any) => f.reason).join('；')}
function originalAnnotation(shot: HistoryProductionDetail['shots'][number]) {
  const plan = shotPlan(shot), annotation = plan.sourceEvidence?.annotation
  return annotation?.description || (annotation?.query ? `原检索描述：${annotation.query}` : '') || plan.originalAnnotation || plan.sourceAnnotation || plan.annotation?.description || detail.value?.job?.candidates?.[shot.shotId]?.find(c => c.assetId === shot.selection?.assetId)?.description || ''
}
function evidenceLabel(shot: HistoryProductionDetail['shots'][number]) {
  const plan = shotPlan(shot), source = plan.sourceEvidence
  const observed = source?.observed
  if (typeof observed === 'string' && observed.trim()) {
    return [source.visualReview === 'sampled_frames' ? '人工抽帧记录（非连续观看）' : '画面观察记录', observed,
      source.sourceSubtitlePolicy ? `原字幕处理：${source.sourceSubtitlePolicy}` : '', source.reviewLimit,
    ].filter(Boolean).join('\n')
  }
  if (observed?.observedImageEvidence) {
    return [
      '人工抽帧记录（非连续观看）', observed.observedImageEvidence,
      observed.burnedTextAndWatermark ? `字幕与水印：${observed.burnedTextAndWatermark}` : '',
      observed.narrativeFit ? `叙事适用性：${observed.narrativeFit}` : '',
      observed.editingNote, observed.visualMethod, observed.sceneCutConclusion,
      observed.sourceListening === 'not_performed' ? '未试听原素材声音。' : '',
    ].filter(Boolean).join('\n')
  }
  const evidence = source?.visualEvidence || plan.visualEvidence || plan.evidence
  if (evidence?.status === 'unavailable') return ['视觉抽检未完成', evidence.reason, evidence.limitations, '素材标注不能代替实际画面核验。'].filter(Boolean).join('\n')
  if (evidence?.status === 'sampled') {
    const observation = evidence.observation || {}, captions = observation.burnedCaptions
    return [
      '自动两帧抽检（非连续观看）', observation.summary,
      observation.eraEvidence ? `可见时代线索：${observation.eraEvidence}` : '',
      captions ? `样本字幕与水印：${captions.present === true ? captions.text || '可见文字' : captions.present === false ? '抽检帧未见' : '无法判断'}` : '',
      observation.frameDifference ? `样本差异：${observation.frameDifference}` : '',
      observation.subjectMotion ? `人物运动线索：${observation.subjectMotion}` : '',
      evidence.reason ? `适用性判断：${evidence.reason}` : '', evidence.limitations,
    ].filter(Boolean).join('\n')
  }
  if (source && !evidence) return '原字幕、镜内切换与人物运动：待人工抽帧检查。原标注不等同于已确认画面。'
  return typeof evidence === 'string' ? evidence : evidence ? pretty(evidence) : shot.visualType === 'image' ? '生成画面，用于叙事补位，不作为历史实录。' : shot.visualType === 'map' ? '示意地图；具体边界与路线依据请结合地图记录审阅。' : '尚无独立画面核验记录；素材标注不等同于已确认画面。'
}
function sourceTechnical(shot: HistoryProductionDetail['shots'][number]) {const evidence = shotPlan(shot).sourceEvidence; const measured = evidence?.measured; return [(evidence?.originalAudio || measured?.originalAudio) === 'muted' ? '原声音已静音' : '', measured?.duration ? `时长 ${Number(measured.duration).toFixed(1)} 秒` : '', measured?.width && measured?.height ? `${measured.width} × ${measured.height}` : ''].filter(Boolean).join(' · ') || '查看下载的编辑记录'}
function pretty(value: unknown) {return JSON.stringify(value,null,2)}
async function deleteProduction() {if (deleting.value || running.value || busy.value || !confirmDelete.value || !detail.value?.deletionSupported) return; const id = episodeId.value; deleting.value = true; generation++; clearTimeout(poll); actionError.value = ''; try {const result = await historyProductionAPI.remove(id); if (result.deleted !== true || result.episodeId !== id) throw Error('删除结果未确认，请刷新页面核对'); if (!disposed && episodeId.value === id) await navigateTo('/remotion')} catch(e:any) {if (!disposed && episodeId.value === id) {actionError.value = e.message || '删除失败'; poll = setTimeout(refresh,12000)}} finally {deleting.value = false}}
watch(currentVideo,() => {videoError.value = false})
watch(episodeId,() => {generation++; detail.value = null; selectedUrl.value = ''; clearTimeout(poll); loading.value = false; refresh()})
onMounted(refresh)
onUnmounted(() => {disposed = true; generation++; clearTimeout(poll)})
</script>
